-- Lot 218 : payloads 511 a 540 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-013","moteur":"chatgpt","payload":"[RaccourcIA — /textureclean]\n\nMISSION\nNettoyer visuellement les textures sans changer le produit. Corrige poussières et petits défauts de capture sur la zone ciblée, conserve grain et détails réels. Ne transforme pas une matière usée en produit neuf sans demande.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Si l’image et l’intention suffisent, génère immédiatement. Ne demande rien de visible ou déjà fourni. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue.\n\nEXÉCUTION\nCorrige poussières et petits défauts de capture sur la zone ciblée, conserve grain et détails réels. Ne transforme pas une matière usée en produit neuf sans demande. Format par défaut : 1:1, haute définition. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la forme, les proportions, le packaging, le logo fourni, les couleurs, matériaux et détails distinctifs du produit.\n\nÉVITER\nÉvite produit déformé, faux packaging, étiquette illisible, reflets incohérents, matière plastique générique et ombre flottante. N’invente aucune donnée et n’ajoute pas automatiquement RaccourcIA, le raccourci ou une interface dans l’image.\n\nSORTIE\nProduis l’image finale. Vérifie silencieusement sujet, proportions, perspective, lumière, matières, texte et artefacts. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"c28dba69526ffd643ba7df455f4c336740df5f7db3d1c09c6bf2720516b6afeb"},{"ref":"RCI-IMG-013","moteur":"claude","payload":"[RaccourcIA — /textureclean]\n\nMISSION\nNettoyer visuellement les textures sans changer le produit. Corrige poussières et petits défauts de capture sur la zone ciblée, conserve grain et détails réels. Ne transforme pas une matière usée en produit neuf sans demande.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Si l’image et l’intention suffisent, génère immédiatement. Ne demande rien de visible ou déjà fourni. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue.\n\nEXÉCUTION\nCorrige poussières et petits défauts de capture sur la zone ciblée, conserve grain et détails réels. Ne transforme pas une matière usée en produit neuf sans demande. Format par défaut : 1:1, haute définition. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la forme, les proportions, le packaging, le logo fourni, les couleurs, matériaux et détails distinctifs du produit.\n\nÉVITER\nÉvite produit déformé, faux packaging, étiquette illisible, reflets incohérents, matière plastique générique et ombre flottante. N’invente aucune donnée et n’ajoute pas automatiquement RaccourcIA, le raccourci ou une interface dans l’image.\n\nSORTIE\nProduis l’image finale. Vérifie silencieusement sujet, proportions, perspective, lumière, matières, texte et artefacts. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"3a26ad5905dc2c9d9a6f1530e8ac6f4dc4944e026d9be9bddcd806fd8ca81343"},{"ref":"RCI-IMG-013","moteur":"gemini","payload":"[RaccourcIA — /textureclean]\n\nMISSION\nNettoyer visuellement les textures sans changer le produit. Corrige poussières et petits défauts de capture sur la zone ciblée, conserve grain et détails réels. Ne transforme pas une matière usée en produit neuf sans demande.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Si l’image et l’intention suffisent, génère immédiatement. Ne demande rien de visible ou déjà fourni. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue.\n\nEXÉCUTION\nCorrige poussières et petits défauts de capture sur la zone ciblée, conserve grain et détails réels. Ne transforme pas une matière usée en produit neuf sans demande. Format par défaut : 1:1, haute définition. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la forme, les proportions, le packaging, le logo fourni, les couleurs, matériaux et détails distinctifs du produit.\n\nÉVITER\nÉvite produit déformé, faux packaging, étiquette illisible, reflets incohérents, matière plastique générique et ombre flottante. N’invente aucune donnée et n’ajoute pas automatiquement RaccourcIA, le raccourci ou une interface dans l’image.\n\nSORTIE\nProduis l’image finale. Vérifie silencieusement sujet, proportions, perspective, lumière, matières, texte et artefacts. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"416936e7be4bfc30b6aab9bcaed30d935bb0ec01c3a4e3e6a3be292a96d9a642"},{"ref":"RCI-IMG-014","moteur":"chatgpt","payload":"[RaccourcIA — /colorswap]\n\nMISSION\nModifier uniquement une couleur cible. Masque précisément la zone, conserve ombres, reflets et matière. Demande la couleur ou propose trois teintes si le choix est ouvert.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Si l’image et l’intention suffisent, génère immédiatement. Ne demande rien de visible ou déjà fourni. Aucune question si le contexte suffit.\n\nEXÉCUTION\nMasque précisément la zone, conserve ombres, reflets et matière. Demande la couleur ou propose trois teintes si le choix est ouvert. Format par défaut : 1:1, haute définition. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. N’invente aucune donnée et n’ajoute pas automatiquement RaccourcIA, le raccourci ou une interface dans l’image.\n\nSORTIE\nProduis l’image finale. Vérifie silencieusement sujet, proportions, perspective, lumière, matières, texte et artefacts. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"a2dc75169364e68547078d2b812b5ad79bbf6ae2c3ca967277aa6fdd4d2a0973"},{"ref":"RCI-IMG